INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('3D','(?<=\b[12]\d{3}\b).*\b((Blu[-]?ray|BD)?3D|((H(alf)?|F(ull)?).?)?(O(ver)?.?U(nder)?|S(ide)?[\W_]?B(y)?.?S(ide)?))\b','i0Ngyx/2','Matches 3D stereoscopic format tags in two branches.
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('4K4U','(?<=^|[\s.-])4K4U\b',NULL,'Banned for Low Quality');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('AAC','\bAAC(\b|\d)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('ABM','(?<=^|[\s.-])ABM\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Movie Upscale','(?<=\b[12]\d{3}\b).*\b(AI(US)?[ ._-]?(Enhanced)?|Up[ ._-]?scale(d)?|Re[ ._-]?Grade(d)?|Topaz[ ._-]?Enhanced)\b',NULL,'Matches AI Upscales');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('AJP69','(?<=^|[\s.-])AJP69\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Amazon Prime','\bAMZN\b|\bAMAZON[ ._-]WEB[ ._-]?(DL|RIP)?\b','K6HrsR/4','Matches Amazon Prime Video source tags in both abbreviated (`AMZN`) and full (`AMAZON WEB-DL` / `AMAZON WEBRIP`) forms. Separators between words can be a space, dot, underscore, or hyphen, and the separator between `WEB` and `DL`/`RIP` is optional entirely. Word boundaries are enforced on both patterns to prevent partial matches.
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('AOC','(?<=^|[\s.-])AOC\b',NULL,'Banned for Excessive Audio Streams');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('APEX','(?<=^|[\s.-])APEX\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Apple TV+','\b(ATVP|APTV|Apple TV\+)\s*\b',NULL,'Apple TV+ is an American subscription OTT streaming service owned and operated by Apple Inc. Launched on November 1, 2019, it offers a selection of original production film and television series called Apple Originals.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('AROMA','(?<=^|[\s.-])AROMA\b',NULL,'Banned for Retagging');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Audio Description','\b(Audio[ ._-]?Description)\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('ATELiER','(?<=^|[\s.-])ATELiER\b',NULL,'Matches "ATELiER" when preceded by whitespace, a hyphen or dot');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Atmos','\b(ATMOS|DDPA)(\b|\d)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('AV1','\bAV1\b',NULL,'AV1, or AOMedia Video 1, is a video coding format that compresses video files and streams while maintaining high quality.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Black & White','(?<=\b[12]\d{3}\b).*\b((B(lack)?[ ._-]?(out|(and|[n&])?[ ._-]?(W(hite)?|Chrome))))\b(?!$)',NULL,'Black and White colour grading. This regex matches a 4-digit number (optionally surrounded by parentheses), followed by any amount of text, and then detects references to "black and white" in various formats. It supports `blackwhite` (no spaces), `black and white`, `black-white`, "`black & white`, `black/white`, as well as shorthand `BW` and `B&W`, while excluding invalid variations like `b w`, `b-w`, or `b/w`');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('BBC iPlayer','\b(iP(layer)?)(?=[\W_]+WEB[ ._-]?(DL|RIP)\b)',NULL,'BBC iPlayer is a video on demand service from the BBC. The service is available over-the-top on a wide range of devices, including mobile phones and tablets, personal computers and smart televisions. iPlayer services delivered to UK-based viewers are free from commercial advertising. ');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('BeyondHD','(?<=^|[\s.-])BeyondHD\b',NULL,'Banned Due to only doing Full Discs');
