INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('CMRG','(?<=^|[\s.-])CM(a)?R(io)?G\b',NULL,'Prolific WEB-DL group. ');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Crave','\bCRAV\b|\bCRAVE[ ._-]WEB[ ._-]?(DL|RIP)?\b',NULL,'Crave (originally CraveTV) is a Canadian subscription video on demand service. The service competes directly with other subscription-based over-the-top streaming services operating in Canada, primarily against American-based services. The service features Bell Media original programming, exclusive Canadian access to programming acquired from several U.S. television and streaming services, and various theatrically-released films. Crave''s major programming supplier is Warner Bros. Discovery (HBO / Max and Warner Bros. films). Starz, offered in partnership with Lionsgate.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('CREATiVE24','(?<=^|[\s.-])CREATiVE24\b',NULL,'Banned for Bloated Garbage');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('CRFW','(?<=^|[\s.-])CRFW\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('CRiSC','(?<=^|[\s.-])CRiSC\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Criterion Channel','\b(CRiT)\b',NULL,'The Criterion Channel is a subscription-based streaming service launched on April 8, 2019, by The Criterion Collection. Available in the United States and Canada, it features a rich library of films, including Criterion Collection releases with special features, curated playlists, temporarily licensed titles, and original content such as academic overviews and introductions. The Channel also showcases Janus-owned titles not yet available on physical media and maintains a collaborative relationship with Warner Bros. Discovery''s Max platform. Perfect for cinephiles, the service brings a curated cinematic experience to the digital space.');
