INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Disney+','\b(DSNP|DSNY(P)?|Disney\+)\s*\b',NULL,'Disney+ is an American subscription video on-demand over-the-top streaming media service that primarily distributes films and television shows produced by Walt Disney Studios and Disney Television Studios, with dedicated content hubs for Disney''s flagship brands; Disney, Pixar, Marvel, Star Wars, National Geographic, ESPN, Hulu and Star.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Dolby Digital','\bDD[^a-z+]|(?<!e-?)\b(ac-?3)\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Dolby Digital +','\bDD[P+]|\b(e[-_. ]?ac3)\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Dolby Vision','\b(DV|Dovi|Dolby[ .]?Vision)\b',NULL,'Dolby Vision is a high dynamic range (HDR) video format that uses dynamic metadata to deliver enhanced brightness, contrast, and color on a scene-by-scene or frame-by-frame basis, providing superior picture quality. This pattern excludes matches where Dolby Vision is associated with SDR (Standard Dynamic Range) or HLG (Hybrid Log-Gamma), ensuring it focuses on Dolby Vision-specific terms.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DON','(?<=^|[\s.-])DON\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Dropout TV','\b(DRPO)\b',NULL,'Dropout is an American comedy subscription streaming service run by the production company of the same name (formerly CollegeHumor), founded in September 2018. Its ad-free original shows are mainly composed of live play, such as Dimension 20 hosted by Brennan Lee Mulligan, and improv comedy and panel shows like Game Changer, Make Some Noise (both hosted by Dropout owner and CEO Sam Reich), and Very Important People hosted by Vic Michaelis. Dropout''s series often feature a rotating cast of regular comedians and performers.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DRX','(?<=^|[\s.-])DRX\b',NULL,'Banned for Non Retail Audio');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS','\bDTS(\b|\d)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS Basic','DTS[ .]?[1-9]',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS-ES','dts[-. ]?es\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS-HD HRA','dts[-. ]?(hd[. ]?)?(hra?|hi\b)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS-HD HRA ES','dts[-. ]?(es|(hd[. ]?)?(hr|hi))',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS-HD MA','\b(dts[-_. ]?(ma|hd([-_. ]?ma)?|xll))(\b|\d)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('DTS-X','\b(dts[-_. :]?x)\b(?!\d)',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Dual Audio','\bDual[ ._-]?(Audio)?\b|\b(JA|ZH|KO)(?= ?\+ ?.*?\b(EN))|\b(EN)(?= ?\+ ?.*?\b(JA|ZH|KO))\b',NULL,'Matches releases with Dual Audio; Media releases that contain two language tracks - typically the original language (such as Japanese) along with an English dub, allowing viewers to switch between either audio track while watching the same video content.');
