INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Movie Extras','(?<=\b[12]\d{3}\b).*\b(Extra(s)?|Bonus|Deleted[ ._-]?Scene(s)?|Extended[ ._-]?Clip(s)?|Special[ ._-]?Feature(s)?)\b',NULL,'Extras, Special Features, Featurettes, etc');
