INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Full Disc','^(?!.*\b((?<!HD[-_. ]|HD)DVD|BDRip|MKV|XviD|WMV|d3g|(BD)?REMUX|^(?=.*1080p)(?=.*HEVC)|[xh][-_. ]?26[45]|German.*[DM]L|((?<=\d{4}).*German.*([DM]L)?)(?=.*\b(AVC|HEVC|VC[-_. ]?1|MVC|MPEG[-_. ]?2)\b))\b)(((?=.*\b(Blu[-_. ]?ray|BD|HD[-_. ]?DVD)\b)(?=.*\b(AVC|HEVC|VC[-_. ]?1|MVC|MPEG[-_. ]?2|BDMV|ISO)\b))|^((?=.*\b(((?=.*\b((.*_)?COMPLETE.*|Dis[ck])\b)(?=.*(Blu[-_. ]?ray|HD[-_. ]?DVD)))|3D[-_. ]?BD|BR[-_. ]?DISK|Full[-_. ]?Blu[-_. ]?ray|^((?=.*((BD|UHD)[-_. ]?(25|50|66|100|ISO)))))))).*|(AVC|DVD5|DVD9|MPEG[-]?2|NTSC|\bPAL\b|VC[-]?1|VOB[-_. ]?IFO|COMPLETE[-_. ]?(UHD)?[-_. ]?BLU[-_. ]?RAY|BR[-]?DISK)',NULL,'A Full Disc release refers to a complete copy of a physical media disc, such as a DVD or Blu-ray, preserving all original content including menus, bonus features, and multiple audio or subtitle tracks. Unlike compressed or re-encoded formats, Full Disc files maintain the full structure and quality of the original disc, often stored as ISO files or folders like BDMV for Blu-rays. These releases are ideal for users seeking an authentic, unaltered experience identical to using the physical disc.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Geek','(?<=^|[\s.-])Geek\b',NULL,'');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('GNOME','(?<=^|[\s.-])GNOME\b',NULL,'Matches "GNOME" when preceded by whitespace, a hyphen or dot');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Google TV','\bPLAY[ ._-]WEB[ ._-]?(DL|RIP)\b|\[[^\]]*\bPLAY\b[^\]]*\]',NULL,'Google TV, formerly known as Google Play Movies & TV, is a digital distribution service for movies and television series developed by Google. Launched in 2011 as part of the Google Play product line, the service offers search and discovery of video titles across multiple streaming services, including rental or purchase options, alongside watchlist features for accessing titles from eligible devices and platforms. In September 2020, it was relaunched as Google TV.');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('GS88','(?<=^|[\s.-])GS88\b',NULL,'');
