INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('HBO Max','\b(HMAX|HBOM)\b|\bHBO[ ._-]?MAX[ ._-]WEB[ ._-]?(DL|RIP)\b',NULL,'HBO Max is an American subscription video-on-demand streaming service that offers a range of original programming and content from WarnerMedia''s vast library, encompassing brands such as Warner Bros., CNN, Cartoon Network, TBS, and Turner Classic Movies. In mid-to-late 2023, HBO Max underwent a rebranding to "Max".');
INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('HDMaNiAcS','(?<=^|[\s.-])HDMaNiAcS\b',NULL,'');
