INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('HDR10+','\bHDR10.?(\+|P(lus)?\b)',NULL,'This regex matches `HDR10` when followed by either a plus sign `+`, `P`, or `Plus`');
