INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('iTunes','\b(iT(unes)?)[ ._-]WEB[ ._-]?(DL|RIP)\b|\[[^\]]*\biT\b[^\]]*\]',NULL,'iTunes began offering video content in October 2005 with the release of iTunes 6. At launch, the iTunes Store provided popular TV shows from ABC, Disney Channel, and other networks. Users could purchase and view video content, such as episodes of Desperate Housewives, Lost, That''s So Raven, and The Suite Life of Zack & Cody.
