INSERT INTO regular_expressions (name,pattern,regex101_id,description) VALUES ('Max','\b((?<!HBO[ ._-])MAX)[ ._-]WEB[ ._-]?(DL|RIP)\b|\[[^\]]*\bMAX\b[^\]]*\]',NULL,'Max, formerly (and in some regions still) known as HBO Max, is an American subscription video on-demand over-the-top streaming service. The platform offers content from the libraries of Warner Bros., Discovery, HBO, CNN, Cartoon Network, Adult Swim, Animal Planet, TBS, TNT, Eurosport, and their related brands.');
