INSERT INTO custom_formats (name,description,include_in_rename) VALUES ('Full Disc (Quality Match)','Matches Full Discs using a Radarr Quality Match',0);
INSERT INTO custom_formats (name,description,include_in_rename) VALUES ('HDR','Matches the ''HDR'' Regex Pattern',0);
